package sh.belfry.core.model

import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.long
import sh.belfry.core.Vectors
import sh.belfry.core.nostr.s
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/** vectors/ticket-prices.json (belfry-ios c9b59be, generated by running the server's price_of). */
class TicketPricesVectorsTest {
    private val v = Vectors.load("ticket-prices.json")

    @Test
    fun asTheServerSays() {
        val cases = (v["cases"] as JsonArray).map { it as JsonObject }
        assertTrue(cases.size >= 34)
        for (c in cases) {
            val name = c.s("name")
            val tags = (c["tags"] as JsonArray).map { t -> (t as JsonArray).map { it.jsonPrimitive.content } }
            val t = Prices.of(tags, c["now"]!!.jsonPrimitive.long)
            val p = t.price
            val got = JsonObject(linkedMapOf(
                "priced" to JsonPrimitive(t.priced),
                "amount" to JsonPrimitive(p?.amount ?: ""),
                "currency" to JsonPrimitive(p?.currency ?: ""),
                "vat" to JsonPrimitive(p?.vat ?: ""),
                "vat_included" to JsonPrimitive(p?.vatIncluded ?: false),
                "until" to (p?.until?.let { JsonPrimitive(it) } ?: JsonNull),
                "on_sale" to JsonPrimitive(t.onSale),
            ))
            val want = c["out"] as JsonObject
            for (k in want.keys) assertEquals(want[k], got[k], "$name: $k")
            assertEquals(c.s("line"), Prices.words(t), "$name: line")
        }
    }
}
